transforms.result:
.readings-grid { display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 0.5rem; }
.reading-box {
  display: flex; flex-direction: column; align-items: center;
  padding: 0.5rem; border-radius: 0.5rem; border: 1px solid rgba(255,255,255,0.06);
}
.reading-box.voltage { background: rgba(245,158,11,0.08); }
.reading-box.current { background: rgba(34,197,94,0.08); }
.reading-box.resistance { background: rgba(6,182,212,0.08); }
.reading-box.power { background: rgba(239,68,68,0.08); }
.reading-box.resistivity { background: rgba(168,85,247,0.08); }
.r-label { font-size: 0.7rem; color: #64748b; }
.r-value { font-size: 1.1rem; font-weight: 700; font-family: monospace; }
.reading-box.voltage .r-value { color: #fbbf24; }
.reading-box.current .r-value { color: #4ade80; }
.reading-box.resistance .r-value { color: #67e8f9; }
.reading-box.power .r-value { color: #f87171; }
.reading-box.resistivity .r-value { color: #c084fc; }
.reading-box.charging { background: rgba(34,197,94,.12); }
.reading-box.charging .r-value { color: #4ade80; }
.reading-box.discharging { background: rgba(239,68,68,.12); }
.reading-box.discharging .r-value { color: #f87171; }
.r-unit { font-size: 0.65rem; color: #475569; }
.rc-section { display: flex; flex-direction: column; gap: .5rem; }
.rc-grid { grid-template-columns: 1fr 1fr; }
.lamp-section { display: flex; flex-direction: column; gap: .5rem; }
.lamp-grid { grid-template-columns: 1fr 1fr 1fr; }
.reading-box.light { background: rgba(251,191,36,.08); }
.reading-box.light .r-value { color: #fbbf24; }
.reading-box.heat { background: rgba(239,68,68,.08); }
.reading-box.heat .r-value { color: #f87171; }
.reading-box.brightness { background: rgba(168,85,247,.08); }
.reading-box.brightness .r-value { color: #c084fc; }
.lamp-visual { display: flex; align-items: center; gap: .75rem; padding: .5rem; }
.lamp-bulb { font-size: 2rem; transition: opacity .3s; }
.lamp-bar-bg { flex: 1; height: 12px; background: #1e2530; border-radius: 6px; overflow: hidden; }
.lamp-bar-fill { height: 100%; background: linear-gradient(90deg, #f59e0b, #fbbf24, #fde047); border-radius: 6px; transition: width .3s; }
.galv-section { display: flex; flex-direction: column; gap: .5rem; }
.galv-grid { grid-template-columns: 1fr 1fr; }
.galv-gauge { display: flex; flex-direction: column; align-items: center; padding: .5rem; }
.galv-svg { width: 100%; max-width: 220px; height: auto; }
.galv-sensitivity { font-size: .75rem; color: #c084fc; margin-top: .25rem; }
.wheatstone-section { display: flex; flex-direction: column; gap: .5rem; }
.wheatstone-grid { grid-template-columns: 1fr 1fr; }
.reading-box.balanced { background: rgba(34,197,94,.15); border: 1px solid rgba(34,197,94,.3); }
.reading-box.balanced .r-value { color: #4ade80; }
.bridge-status { display: flex; align-items: center; gap: .4rem; padding: .5rem; border-radius: 6px; font-size: .78rem; font-weight: 600; }
.bridge-status.balanced { background: rgba(34,197,94,.12); color: #4ade80; border: 1px solid rgba(34,197,94,.25); }
.bridge-status.unbalanced { background: rgba(245,158,11,.1); color: #fbbf24; border: 1px solid rgba(245,158,11,.2); }
.bridge-icon { font-size: 1.1rem; }
.vdiv-section { display: flex; flex-direction: column; gap: .5rem; }
.vdiv-grid { grid-template-columns: 1fr 1fr; }
.vdiv-bar { padding: .5rem; }
.vdiv-label { font-size: .72rem; color: #94a3b8; margin-bottom: .25rem; }
.vdiv-bar-bg { display: flex; height: 16px; border-radius: 8px; overflow: hidden; }
.vdiv-bar-v1 { background: #3b82f6; transition: width .3s; }
.vdiv-bar-v2 { background: #f59e0b; flex: 1; }
.vdiv-legend { display: flex; justify-content: space-between; margin-top: .2rem; font-size: .68rem; }
.leg-v1 { color: #3b82f6; }
.leg-v2 { color: #f59e0b; }

